\begin{tikzpicture}[font=\small,line cap=round,line join=round,scale=0.95]
  \draw[->] (0,0)--(6.4,0) node[right]{Day};
  \draw[->] (0,0)--(0,4.4) node[above]{Temperature (\circC)};
  \foreach \y/\lab in {1/10,2/20,3/30,4/40} {
    \draw (0,\y)--(-0.12,\y) node[left]{\lab};
  }
  \foreach \x/\lab in {1.2/Mon,2.6/Tue,4.0/Wed,5.4/Thu} {
    \draw (\x,0.08)--(\x,-0.08) node[below]{\lab};
  }
  % morning solid
  \draw[line width=1.0pt] (1.2,2.2)--(2.6,2.6)--(4.0,3.0)--(5.4,2.8);
  \foreach \x/\y in {1.2/2.2,2.6/2.6,4.0/3.0,5.4/2.8} {
    \fill (\x,\y) circle (1.6pt);
  }
  % afternoon dashed
  \draw[line width=1.0pt,dashed] (1.2,3.2)--(2.6,3.5)--(4.0,3.6)--(5.4,3.3);
  \foreach \x/\y in {1.2/3.2,2.6/3.5,4.0/3.6,5.4/3.3} {
    \draw[fill=white] (\x,\y) circle (1.6pt);
  }
  \draw[line width=1.0pt] (0.3,4.05)--(0.9,4.05);
  \node[right] at (0.95,4.05){Morning};
  \draw[line width=1.0pt,dashed] (2.6,4.05)--(3.2,4.05);
  \node[right] at (3.25,4.05){Afternoon};
\end{tikzpicture}
